DROP ALL OBJECTS;
CREATE TABLE users (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_name VARCHAR(100) UNIQUE NOT NULL,
 password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(160) NOT NULL, phone VARCHAR(30) UNIQUE NOT NULL,
 email VARCHAR(254) UNIQUE, role VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL,
 status_note TEXT NOT NULL DEFAULT '', avatar_url TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, last_login_at TIMESTAMP WITH TIME ZONE,
 version BIGINT DEFAULT 0
);
CREATE TABLE admins(id BIGINT PRIMARY KEY REFERENCES users(id));
CREATE TABLE customers(id BIGINT PRIMARY KEY REFERENCES users(id),total_bookings INT DEFAULT 0,reward_points BIGINT DEFAULT 0,gender VARCHAR(10),date_of_birth DATE);
CREATE TABLE staffs(birth_year SMALLINT,id BIGINT PRIMARY KEY REFERENCES users(id),identity_number VARCHAR(30) UNIQUE,
 gender VARCHAR(10),date_of_birth DATE,profile_description TEXT,approved_at TIMESTAMP WITH TIME ZONE,
 approved_by BIGINT REFERENCES admins(id),account_rank VARCHAR(20) DEFAULT 'INTERN',average_rating NUMERIC(3,2) DEFAULT 0,experience_years NUMERIC(4,1) DEFAULT 0,total_reviews INT DEFAULT 0,completion_rate NUMERIC(5,2),satisfaction_rate NUMERIC(5,2),status VARCHAR(20) DEFAULT 'OFFLINE',is_online BOOLEAN DEFAULT false);
CREATE TABLE addresses(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id BIGINT REFERENCES customers(id),
 title VARCHAR(100),receiver_name VARCHAR(160),receiver_phone VARCHAR(30),detail_address TEXT,ward VARCHAR(100),district VARCHAR(100),province VARCHAR(100),latitude NUMERIC(10,7),longitude NUMERIC(10,7),note TEXT,is_default BOOLEAN DEFAULT FALSE,
 created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT REFERENCES users(id),notification_type VARCHAR(50),title VARCHAR(255),content TEXT,reference_id BIGINT,payload TEXT DEFAULT '{}',created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,read_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE support_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sender_name VARCHAR(160),email VARCHAR(254),subject VARCHAR(255),message TEXT,status VARCHAR(20) DEFAULT 'RECEIVED',created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE account_sessions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT REFERENCES users(id),
 token_hash VARCHAR(64) UNIQUE,expires_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE staff_candidates(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,payload TEXT NOT NULL,
 status VARCHAR(20) DEFAULT 'PENDING',staff_id BIGINT UNIQUE REFERENCES staffs(id),
 created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE registration_verifications (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,challenge_id VARCHAR(36) NOT NULL UNIQUE,code_hash VARCHAR(255) NOT NULL,
 attempts INTEGER NOT NULL DEFAULT 0,expires_at TIMESTAMP WITH TIME ZONE NOT NULL,sent_at TIMESTAMP WITH TIME ZONE NOT NULL,
 window_started_at TIMESTAMP WITH TIME ZONE NOT NULL,send_count INTEGER NOT NULL DEFAULT 1,
 verification_token_hash VARCHAR(64) UNIQUE,verified_until TIMESTAMP WITH TIME ZONE,consumed_at TIMESTAMP WITH TIME ZONE
);

CREATE TABLE administrative_units(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,province VARCHAR(100),name VARCHAR(100),unit_type VARCHAR(20),effective_from DATE,source_url TEXT);
